 for(const r of records('labor_week_results')){const d=r.data||{},k=d.week_start;if(!k)continue;const x=map.get(k)||{start:k,end:new Date(k+'T12:00:00Z').getUTCDay()===1?addDays(k,6):d.week_end};const h=M.number(d.hours?.amount);if(h!==null){x.hours=h;x.hoursFinal=d.hours?.final===true;}if(x.sales==null){const os=d.operating_sales,ws=d.sales,v=M.number(os?.amount)??M.number(ws?.amount);if(v!==null){x.sales=v;x.salesSource=os&&M.number(os.amount)!==null?'Crumbl operating sales':'Entered weekly sales (unconfirmed)';x.salesFinal=(os||ws)?.final===true;}}map.set(k,x);}
