  const wr=costPerHour(w.end||addDays(w.start,6))||cph,est=wr&&w.hours!=null?w.hours*wr.rate:null,pct=est!=null&&w.sales>0?est/w.sales*100:null,splh=w.hours>0&&w.sales!=null?w.sales/w.hours:null,sun=new Date(w.start+'T12:00:00Z').getUTCDay()===1||!w.end?addDays(w.start,6):w.end,label=short(w.start)+'–'+short(sun).replace(/^[A-Za-z]+ /,w.start.slice(5,7)===sun.slice(5,7)?'':'$&');
  const how=pct!==null?`${N(w.hours)} worked hours × ${money2(wr.rate)} per paid hour from the ${wr.label}, tips excluded, salaried included${w.scheduled!=null?'; '+(w.scheduledBasis==='published'?'confirmed (published) schedule':'scheduled shifts, published and unpublished,')+' was '+N(w.scheduled)+' h':''} = ${money(est)} ÷ ${money(w.sales)} ${w.salesSource} = ${pct.toFixed(1)}%. An estimate until payroll for this week is final.`:w.sales!=null?`${money(w.sales)} ${w.salesSource}. Worked hours for this week are not imported yet, so labor % can't be estimated.`:`${N(w.hours)} worked hours from When I Work. Sales for this week are not on file yet.`;
