 const ratios=data.months.map(m=>m.ratio).filter(v=>v!==null),scale=Math.max(40,Math.ceil(Math.max(target||0,...ratios)/10)*10),pctOf=v=>(Math.min(scale,v)/scale*100).toFixed(1);
 const range=data.months[0]?.start&&data.months.at(-1)?.end?short(data.months[0].start)+' – '+short(data.months.at(-1).end)+', '+year:year;
 const cols=data.months.map(m=>{const v=m.ratio,over=v!==null&&target!==null&&v>target+.05,state_=v!==null?'':m.overlap?'Needs review':m.partial?'Partial':'Books open',label=m.label+' '+year+': '+(v!==null?v.toFixed(1)+'% of sales'+(target!==null?(over?', '+pts(v-target)+' above':', within')+' your '+N(target)+'% goal':''):state_+' · no % yet')+'. Open month details.';
  return '<button type="button" class="wh-col'+(v===null?' open':'')+'" data-wallet-pay-month="'+m.key+'" aria-label="'+E(label)+'"><span class="wh-val'+(v===null?' muted':'')+'">'+(v!==null?v.toFixed(1)+'%':E(state_))+'</span><span class="wh-track"><span class="wh-bar" style="height:'+(v!==null?pctOf(v):'14')+'%">'+(over?'<em style="height:'+((v-target)/v*100).toFixed(1)+'%"></em>':'')+'</span></span><span class="wh-month">'+E(m.label)+(m.partial?'<small>partial</small>':'')+'</span></button>';}).join('');
