const setupNames={books:['Accounting','accountant','accounting','Connect QuickBooks','Start bookkeeping'],entity:['Company','entity provider','entity','Import entity documents','Incorporate with CoverPanda'],insurance:['Insurance','insurance provider','insurance','Import policies','Get covered with CoverPanda'],payroll:['Payroll','payroll provider','payroll','Import payroll reports','Set up CoverPanda Payroll']};
function setupService(key){if(key==='payroll'){payrollConnect();return;}const info=setupNames[key];if(!info)return;const d=dialog(info[0]+' · get started','<p>Use your existing provider or get help from CoverPanda. Records stay organized in this wallet.</p><div class="service-setup-options"><section><h3>I already have records</h3><p>'+(key==='books'?'Connect your QuickBooks company to bring financial results into Accounting.':'Upload existing documents or import a private copy from Google Drive.')+'</p>'+button(info[3],'data-setup-connect')+(key!=='books'?button('Import from Google Drive','data-setup-drive'):'')+'</section><section><h3>I work with a provider</h3><p>Invite your '+info[1]+' with location-specific access to contribute the relevant reports and documents.</p>'+button('Invite my '+info[1],'data-setup-invite')+'</section><section><h3>I need a provider</h3><p>'+({books:'Monthly bookkeeping, cleanup and reporting.',entity:'Formation guidance and preparation of your entity records.',insurance:'Quotes and help reviewing the coverage your business needs.',payroll:'Payroll setup, processing support and reporting.'}[key])+'</p>'+button(info[4],'data-setup-coverpanda',true)+'<small>Review scope and pricing before enrollment. A request does not activate a service.</small></section></div>');d.querySelector('[data-setup-invite]').onclick=()=>{d.close();dispatchEvent(new CustomEvent('fran:invite-provider',{detail:{scope:info[2]}}));};const importRecords=drive=>{d.close();switchTab(drive?'dataroom':'documents');const hub=$('location-document-hub');if(hub)hub.hidden=false;const target=$(drive?'life-drive':'fw-upload-form');if(target){const details=target.closest('details');if(details)details.open=true;target.scrollIntoView({block:'center'});if(drive&&!target.disabled)target.click();else target.querySelector?.('input[type=file]')?.focus();}};d.querySelector('[data-setup-connect]').onclick=()=>{if(key==='books'){d.close();$('connect-qbo')?.click();}else importRecords(false);};d.querySelector('[data-setup-drive]')?.addEventListener('click',()=>importRecords(true));d.querySelector('[data-setup-coverpanda]').onclick=()=>{d.close();dispatchEvent(new CustomEvent('fran:service-profile',{detail:{service:key}}));};}
function setupEntrypoints(){for(const [route,key]of [['books','books'],['company','entity'],['insurance','insurance'],['payroll','payroll']]){const page=$('page-'+route),hdr=page?.querySelector('.wallet-heading')||page?.querySelector('.main-hdr');if(!hdr)continue;let b=hdr.querySelector('[data-wallet-setup]');if(!b){b=document.createElement('button');b.className='wallet-button setup-entry';b.dataset.walletSetup=key;b.textContent='Connections & service';b.onclick=()=>setupService(key);hdr.append(b);}const has=key==='books'?state.books?.length:key==='entity'?(life?.records||[]).some(r=>r.kind==='entity'):key==='insurance'?docs().some(r=>r.data.document_type==='insurance_policy'):records('payroll').length;page.querySelector('.service-start-card')?.remove();if(!has&&key!=='payroll'){const start=document.createElement('section');start.className='service-start-card';start.innerHTML='<h2>Set up your '+setupNames[key][0].toLowerCase()+'</h2>'+sourceProgressView(key)+'<p>Bring your records, invite your provider, or get started with CoverPanda.</p>'+button('Choose how to get started','data-wallet-setup="'+key+'"',true);start.querySelector('button').onclick=()=>setupService(key);hdr.after(start);}}}
function contextualTools(){for(const route of ['books','banking','company'])$('page-'+route)?.querySelectorAll('.main-hdr .context-ai').forEach(b=>b.remove());for(const [route,key]of [['payroll','payroll'],['entity','entity'],['insurance','insurance']]){const page=$('page-'+route);if(!page)continue;page.querySelectorAll('.fran-guide').forEach(x=>x.remove());const hdr=page.querySelector('.wallet-heading')||page.querySelector('.main-hdr');if(!hdr)continue;let action=hdr.querySelector('.context-ai');if(!action){action=document.createElement('button');action.className='wallet-button context-ai';hdr.append(action);}action.innerHTML=icon('spark')+'Ask Fran AI';action.setAttribute('data-wallet-ask',contexts[key][1]);action.dataset.context=key;}}
function answer(question,context){const q=question.toLowerCase(),points=complete(),last=points.at(-1),pay=M.payroll(state,year||'2025'),policies=docs().filter(r=>r.data.document_type==='insurance_policy');let text='',sources=[];
 if(/policy|coverage|insurance|workers|commercial auto|owner.s policy|\bbop\b/.test(q)){
  const chosen=/workers|compensation|\bwc\b/.test(q)?policies.filter(r=>/workers/i.test(r.data.coverage_type)):/\bbop\b|owner/.test(q)?policies.filter(r=>/owner/i.test(r.data.coverage_type)):policies;
  if(/commercial auto|auto policy/.test(q))text='I do not have an identified commercial auto policy in this wallet. I cannot establish its limits from the BOP or workers’ compensation policy. Ask CoverPanda Insurance to add or confirm that coverage.';
  else if(!chosen.length)text='No matching policy with extracted coverage is available in this wallet yet.';
  else{text=chosen.map(r=>{const d=r.data;return /expire|lapse|renew|when|term/.test(q)?d.coverage_type+' with '+d.carrier+' has a stored term ending '+date(d.expiration)+'.':d.coverage_type+' with '+d.carrier+': '+coverageRows(d).map(([l,v])=>l+' '+v).join('; ')+'.';}).join('\n\n')+'\n\nThese are saved policy facts. Cancellation, renewal and endorsement changes are not automatically synchronized.';sources=chosen;}
 }else if(/readiness|lender|loan package|financing package|capital ready/.test(q)){const ready=M.readiness(state,life);text='This wallet’s evidence preparation score is '+ready.score+'%: '+ready.current+' of '+ready.total+' core evidence areas are current.\n\n'+(ready.next.length?'Next evidence to resolve:\n'+ready.next.map(s=>'• '+s.title+': '+s.detail).join('\n'):'The core evidence areas are current. Confirm the lender’s specific requirements before sharing.')+'\n\n'+ready.note;
 }else if(/ownership|owner|entity|formation|legal name|dba|ein/.test(q)){const entity=(life?.records||[]).find(r=>r.kind==='entity')?.data||{},owners=Array.isArray(entity.owners)?entity.owners:[];text=entity.name?'Legal entity: '+entity.name+(entity.dba?'\nDBA: '+entity.dba:'')+(entity.entity_type||entity.jurisdiction?'\nStructure: '+[entity.entity_type,entity.jurisdiction].filter(Boolean).join(' · '):'')+(entity.effective_date?'\nEffective: '+date(entity.effective_date):'')+'\nOwners: '+(owners.length?owners.map(o=>o.name+(M.number(o.percentage)!==null?' · '+o.percentage+'%':' · interest not confirmed')).join('; '):'current roster not confirmed')+(entity.beneficial_owners?.length?'\nPeople behind the parent: '+entity.beneficial_owners.map(o=>o.name+' · '+o.percentage+'% through '+o.through).join('; '):'')+(entity.ownership_confirmed_at?'\nOwnership confirmed by owner: '+date(entity.ownership_confirmed_at):'')+(entity.parent_company?.legal_form_status==='awaiting_review'?'\nExact parent legal name/form is awaiting document review.':'')+'\n\nSource: saved entity record. Original legal records control.':'No structured entity record is available in this wallet yet.';
 }else if(/deadline|compliance|renewal|due next/.test(q)){text=tasks().length?tasks().slice(0,5).map(r=>cleanTitle(r.data.title)+(suggested(r.data)?' (suggested date, confirm)':'')+' — '+date(r.data.due)+'. Source: '+r.data.source).join('\n\n'):'No open deadlines are recorded. This does not establish that all filings are current.';
 }else if(/bank|balance|cash available/.test(q)){text='Available cash across connected deposit accounts is '+money(M.cash(state))+'.\n\n'+M.accounts(state).map(a=>(a.name||'Account')+': '+money(a.available??a.current)+' '+(a.available!=null?'available':'current')+' ('+a.type+').').join('\n')+'\nCredit availability is separate from cash; these balances are point-in-time snapshots.';
 }else if(/labor|payroll|hour|paid|employee|wages/.test(q)||context==='payroll'){
  const latest=pay.months.filter(m=>!m.partial).at(-1),prev=pay.months.filter(m=>!m.partial).at(-2);
  text=/hour/.test(q)?money(pay.cost)+' labor cost ÷ '+num(pay.hours)+' paid hours = '+(pay.hours>0&&pay.cost!==null?'$'+(pay.cost/pay.hours).toFixed(2):'not available')+' per paid hour for '+year+'. This includes employer taxes and reported benefits, and is not an employee wage rate.':/who|employee|people/.test(q)?pay.people.length+' people received positive gross pay in the '+year+' imported history. This is not current headcount. Open Employees for individual totals.':latest&&prev?'In '+latest.label+' '+year+', labor cost was '+money(latest.cost)+', compared with '+money(prev.cost)+' in '+prev.label+'. Paid hours were '+num(latest.hours)+' versus '+num(prev.hours)+'.\n\n'+(latest.ratio!==null?'Labor was '+latest.ratio.toFixed(1)+'% of matching reported sales. ':'')+'Payroll is grouped by payment date, so timing can affect the comparison.':'More payroll history is needed to compare months.';
  sources=docs().filter(r=>['payroll_export','schedule_export','payroll_journal','payroll_report'].includes(r.data.document_type));
 }else if(/profit|income|revenue|accounting|overview|business/.test(q)){
  const lastCalendar=new Date();lastCalendar.setUTCDate(1);lastCalendar.setUTCMonth(lastCalendar.getUTCMonth()-1);const expected=lastCalendar.toISOString().slice(0,7),askedMonth=points.find(p=>q.includes(p.label.toLowerCase())),p=askedMonth||(/last month/.test(q)?points.find(p=>p.key===expected):last);
  if(!p)text='I do not have the requested month in your saved monthly books. '+(last?'The latest reported month is '+last.label+'. ':'')+'Ask CoverPanda Accounting for an updated report.';
  else if(/6|six|trailing/.test(q)){const total=M.trailing(points,p.key);text=total===null?'I need six consecutive complete calendar months of net income to calculate that period.':'Net income across the six reported months ending '+p.label+' totals '+money(total)+'. This uses QuickBooks monthly net income, not the annual tax return. '+(p.key!==expected?'The latest available endpoint is '+p.label+'; it is not the six months ending last month.':'');}
  else text=p.label+': revenue '+money(p.income)+', gross profit '+money(p.gross)+', net income '+money(p.net)+'.'+(p.income>0&&p.net!==null?' Net margin was '+(p.net/p.income*100).toFixed(1)+'%.':'')+'\n\nSource: '+(state.books?.[0]?.company||'QuickBooks')+' monthly reports. A completed calendar month does not mean the books are closed.';
 }else text='I can answer questions about the saved monthly books, bank balances, payroll history, policy limits and deadlines. I do not have enough structured evidence to answer this specific question confidently. Your CoverPanda team can help investigate it.';
 return {text,sources};
}
function ask(question='',context='books'){const scope=contexts[context]||['Your wallet','Give me an overview of my business'];const d=dialog('Fran AI · '+scope[0],'<div class="wallet-ai-intro">'+icon('spark')+'<p>Saved-record summaries and document search are included. Generated AI answers require a paid monthly plan and available allowance. Your service team is a separate conversation.</p></div><div id="wallet-ai-history" aria-live="polite"></div><form id="wallet-ai-form"><label for="wallet-ai-question">Ask about this part of your business</label><div><input id="wallet-ai-question" name="question" required maxlength="600" placeholder="Ask a question about these records"><button class="wallet-button primary">Ask Fran</button></div></form><div class="wallet-ai-suggestions">'+scope.slice(1).map(q=>button(E(q),'data-ai-suggest="'+E(q)+'"')).join('')+'</div>'+button(icon('chat')+'Ask '+supportName(context),'data-wallet-service="'+context+'"'),false);
 const asked=[];let busy=false;const token=epoch;
 d.exportConversation=()=>{if(busy)throw Error('Wait for the answer to finish before saving.');const messages=[];for(const article of d.querySelector('#wallet-ai-history').children){if(article.dataset.savedRole){messages.push({role:article.dataset.savedRole,text:article.querySelector('p').textContent});continue;}const copy=article.cloneNode(true),question=copy.querySelector(':scope > h3');if(question){messages.push({role:'user',text:question.textContent});question.remove();}copy.querySelectorAll('button,input,select,label,.ask-inline-actions').forEach(n=>n.remove());const text=copy.textContent.trim();if(text)messages.push({role:article.classList.contains('ask-setup-turn')?'setup':'assistant',text});}return messages;};
 d.restoreConversation=messages=>{if(busy)throw Error('Wait for the answer to finish before opening a saved chat.');const history=d.querySelector('#wallet-ai-history');history.replaceChildren();asked.length=0;for(const message of messages){const article=document.createElement('article');article.dataset.savedRole=message.role;const label=document.createElement('small');label.textContent=message.role==='user'?'YOU':message.role==='setup'?'SAVED SETUP STEP':'SAVED ANSWER · NOT REFRESHED';const text=document.createElement('p');text.style.whiteSpace='pre-wrap';text.textContent=message.text;article.append(label,text);history.append(article);if(message.role==='user')asked.push(message.text);}history.scrollTop=history.scrollHeight;};
 const run=async q=>{if(!q||busy)return;busy=true;const form=d.querySelector('form'),submit=form.querySelector('button');submit.disabled=true;const a=answer(q,context),history=d.querySelector('#wallet-ai-history'),article=document.createElement('article');article.innerHTML='<h3>'+E(q)+'</h3><p>'+E(a.text)+'</p><div class="wallet-document-links">'+a.sources.filter(r=>relevantDoc(r,context)).map(sourceButton).join('')+'</div><p role="status">Searching this wallet’s document evidence…</p>';history.append(article);article.scrollIntoView({block:'nearest'});
 try{const result=await api('ask_documents',{question:q,context,history:asked.slice(-4)});if(token!==epoch||!d.open)return;asked.push(q);const status=article.querySelector('[role=status]');status.textContent=result.notice+(result.allowance?' '+result.allowance.remaining+' of '+result.allowance.limit+' AI requests remain in this paid period.':'');
 if(result.ai_access?.reason==='paid_plan_required'){const upgrade=document.createElement('div');upgrade.className='wallet-ai-upgrade';status.after(upgrade);window.mountFranAIUpgrade?.(upgrade,{question:q,context});}
 if(result.answer){article.querySelector('p').textContent=result.answer;}else{const label=document.createElement('small');label.textContent='Saved dashboard summary · no AI generation';article.querySelector('p').before(label);}
 const coverage=result.coverage||[],incomplete=coverage.filter(x=>x.status==='incomplete');
 article.insertAdjacentHTML('beforeend','<details class="wallet-source-results" '+(result.answer?'':'open')+'><summary>Document evidence · '+(result.sources||[]).length+' matching excerpts</summary>'+(result.sources||[]).map(x=>'<article><h4>'+E(x.citation+' · '+x.name)+'</h4><small>'+E(x.locator)+' · '+E(x.status.replaceAll('_',' '))+'</small><blockquote>'+E(x.content)+'</blockquote>'+(x.document_id?button('Open original','data-wallet-preview="'+E(x.document_id)+'"'):'')+'</article>').join('')+(!result.sources?.length?'<p>No matching readable excerpts found. This does not prove the information is absent from the originals.</p>':'')+'</details><details class="wallet-source-results"><summary>Library coverage · '+coverage.length+' documents'+(incomplete.length?' · '+incomplete.length+' incomplete':'')+'</summary>'+coverage.map(x=>'<p><strong>'+E(x.name)+'</strong><br>'+E(x.status.replaceAll('_',' '))+' · '+(x.readable_pages||0)+' / '+(x.pages??'?')+' readable pages or rows · indexed '+E(x.indexed_at?new Date(x.indexed_at).toLocaleString():'not yet')+'</p>').join('')+'</details>'+button('Ask my representative about this','data-wallet-service="'+E(context)+'" data-note="'+E(('Please review: '+q).slice(0,175))+'"'));
 }catch(error){if(token===epoch&&d.open)article.querySelector('[role=status]').textContent='Document search unavailable: '+error.message+' The saved-field answer above is limited to dashboard records.';}finally{busy=false;submit.disabled=false;}};
 d.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.target.question.value.trim());e.target.reset();};d.querySelectorAll('[data-ai-suggest]').forEach(b=>b.onclick=()=>run(b.dataset.aiSuggest));if(question)run(question);
}
