function goals(){const existing=state.goals?.find(g=>g.metric==='labor_percent'),data=M.payroll(state,year),target=existing?.target,eligible=data.months.filter(m=>!m.partial&&m.ratio!==null);const d=dialog('Your labor goal','<p>Set your own labor cost target as a percentage of sales. Compare like periods and confirm import completeness before acting.</p><form id="wallet-goal-form"><label>Labor target (%)<input name="target" type="number" min="1" max="100" step="0.1" value="'+(target||30)+'" required></label><button class="wallet-button primary">Save goal to wallet</button><p role="status"></p></form><div class="wallet-goal-history">'+(target?eligible.map(m=>'<div><span>'+m.label+' '+year+'</span><strong>'+m.ratio.toFixed(1)+'%</strong>'+badge(m.ratio<=target?'Within goal':'Above goal',m.ratio<=target?'good':'notice')+'</div>').join(''):'<p>Your progress will appear once you save a goal.</p>')+'</div>'+button('Create milestone card','data-wallet-milestone'));
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(goalBusy)return;const wallet=state.wallet.id,form=e.target,target=Number(form.target.value);goalBusy=true;form.querySelector('button').disabled=true;try{await api('save_goal',{metric:'labor_percent',target});if(state.wallet.id!==wallet)return;state.goals=[...(state.goals||[]).filter(g=>g.metric!=='labor_percent'),{metric:'labor_percent',target}];form.querySelector('[role=status]').textContent='Goal saved to this wallet.';payroll();}catch(error){form.querySelector('[role=status]').textContent=error.message;}finally{goalBusy=false;form.querySelector('button').disabled=false;}};
}
function milestone(){const data=M.payroll(state,year),goal=state.goals?.find(g=>g.metric==='labor_percent'),hit=goal?data.months.filter(m=>!m.partial&&m.ratio!==null&&m.ratio<=goal.target).at(-1):null,title=hit?'A month within my labor goal.':'My business, coming into focus.',text=hit?'I reviewed a month within my labor goal with Fran.':'I brought my payroll history into my business wallet with Fran.',d=dialog('Celebrate a useful milestone','<div class="wallet-milestone"><span>Fran</span>'+icon(hit?'chart':'people')+'<h2>'+title+'</h2><p>'+(hit?hit.label+' '+year+' · based on imported payroll and reported sales':year+' payroll history, organized and ready to understand.')+'</p></div><p>Share the achievement without employee names, financial amounts or your private wallet URL.</p>'+button('Copy share text','id="wallet-copy-milestone"',true)+'<p id="wallet-share-status" role="status"></p>');d.querySelector('#wallet-copy-milestone').onclick=async()=>{try{await navigator.clipboard.writeText(text+' https://franwallet.com');$('wallet-share-status').textContent='Copied. Share it wherever you choose.';}catch{$('wallet-share-status').textContent=text+' https://franwallet.com';}};}
