 const d=dialog(x.title,'<p class="wallet-note">'+E(x.period)+' · '+E(x.source)+'</p><div class="wallet-analysis-callout"><h3>What Fran found</h3><p>'+E(x.finding)+'</p></div><h3>What needs verification</h3><p>'+E(x.uncertainty)+'</p><h3>What a useful resolution looks like</h3><p>'+E(x.outcome)+'</p><div class="wallet-next">'+button('Inspect evidence','data-priority-evidence',true)+button('Prepare request','data-priority-request')+'</div>'+(related.length?'<h3>Related requests</h3>'+related.map(r=>'<p>'+E((r.ticket?.status||'awaiting_review').replaceAll('_',' '))+' · '+E(r.data.note)+'</p>').join(''):'<p>No related request has been saved yet.</p>')+button('Snooze for 7 days','data-priority-snooze')+'<p class="wallet-note">Snoozing hides this priority on this browser only; it does not change a deadline or resolve a request.</p>');
 d.querySelector('[data-priority-evidence]').onclick=()=>{if(x.action==='finance')accountAnalysis('net');else if(x.action==='debt')debtDetail();else if(x.action==='payroll')payMonth(x.month);else if(x.action==='insurance'&&x.recordId)preview(x.recordId);else taskDetail(x.recordId);};
