function freshness(){
 const books=state.books?.[0],last=complete().at(-1),pay=records('payroll').filter(r=>String(r.data.date).startsWith(year||'2025')),policy=docs().filter(r=>r.data.document_type==='insurance_policy');
 const latest=rows=>rows.map(r=>r.data.imported_at||r.updated_at||r.created_at).filter(Boolean).sort().at(-1);
 const stamp=v=>v?new Date(v).toLocaleString():'Not recorded';
 const configs=[
 ['wallet-home','Combined snapshots',last?.label||'Period missing',books?.last_synced,'Awaiting review','Reports, balances and deadlines have different dates. Open each number for its period and evidence.','books'],
 ['wallet-accounting-insight','QuickBooks monthly reports',last?.label||'Period missing',books?.last_synced,books?'Awaiting review':'Incomplete','A completed calendar month is not a confirmed accounting close.','books'],
 ['wallet-finance-intro','Connected bank snapshots','Point-in-time balances',(state.banks||[]).map(x=>x.last_synced).filter(Boolean).sort()[0],state.banks?.length?'Awaiting review':'Incomplete','Oldest connection update shown. Snapshot balances are not live available funds.','spend'],
 ['wallet-payroll','Gusto / imported payroll',year||'Reporting year missing',latest(pay),pay.length?'Awaiting review':'Incomplete','Imported periods and people paid do not establish complete payroll or current headcount.','payroll'],
 ['wallet-insurance','Saved carrier policies',policy.map(r=>r.data.effective+' to '+r.data.expiration).filter((v,i,a)=>a.indexOf(v)===i).join('; ')||'Term missing',latest(policy),policy.length?'Awaiting review':'Incomplete','Policy terms are on file; cancellation and endorsement updates require confirmation.','insurance'],
 ['wallet-compliance','Entity documents and owner updates','Recorded obligations',latest(life?.records||[]),'Awaiting review','Dates and completed reminders do not certify current legal standing.','entity']];
 for(const [id,source,period,updated,status,note,key] of configs){const host=$(id);if(!host)continue;host.querySelector('.wallet-freshness')?.remove();const box=document.createElement('details');box.className='wallet-freshness';const list=id==='wallet-payroll'&&host.querySelector('.wallet-records-list');box.innerHTML=(list?'<summary><span>Review status</span><small>'+E(status)+' · '+E(status==='Awaiting review'?'your bookkeeper has not checked these '+period+' imports yet':'some payroll records are missing')+'</small></summary>':'<summary>'+E(status)+' · '+E(period)+' · '+E(source)+'</summary>')+badge(status,'notice')+'<div><strong>'+E(source)+'</strong><small>Period: '+E(period)+' · Updated: '+E(stamp(updated))+'</small><p>'+E(note)+'</p></div>'+button('Request review','data-wallet-service="'+key+'" data-note="'+E(('Please review completeness and freshness of '+source+' for '+period+'.').slice(0,175))+'"');(list||host).append(box);}
}
function providerCard(key){
 const names={books:'Your bookkeeper',insurance:'Your insurance team',entity:'Company & compliance',payroll:'Your payroll team',spend:'Finance support'};
 return '<section class="wallet-provider-card"><span class="wallet-provider-mark">'+icon(key==='insurance'?'shield':'chat')+'</span><div><small>'+E(names[key])+'</small><h3>'+E(supportName(key))+'</h3><p>Keep questions, source records and follow-through together.</p></div>'+button('Message '+supportName(key),'data-wallet-service="'+key+'"',true)+'</section>';
}
function contextualPrompts(){
 const spec=[['bizplan','books','Plan your next chapter','How much cash does this opening or expansion need?','What assumptions should I stress-test before seeking funding?'],['books','books','Understand this month','What changed in gross margin this month?','Which costs take the largest share of sales?'],['banking','spend','Make your cash work for you','What do these balances tell me about my next decision?','Which cash and debt records are missing?'],['payroll','payroll','Build a plan your team can use','Why do payroll and accounting labor differ?','What must we verify before publishing the next schedule?'],['insurance','insurance','Keep coverage close to your business','What is covered, and what needs confirmation?','Which policy renewals should I prepare for?'],['entity','entity','Move the business forward','Which entity records are needed for opening?','What changes when I add my second location?'],['dataroom','debt','Be ready for the next opportunity','What evidence is missing for a lender?','How should I prepare a recipient-specific room?']];
 for(const [route,key,title,...qs]of spec){const page=$('page-'+route);if(!page)continue;page.querySelectorAll('.wallet-fran-context').forEach(n=>n.remove());if(route==='payroll'&&page.querySelector('.wallet-help'))continue;const el=document.createElement('section');el.className='wallet-fran-context';el.innerHTML='<span class="wallet-fran-orb" aria-hidden="true">'+icon('spark')+'</span><div><small>FRAN · '+E(state.wallet.name)+'</small><h3>'+E(title)+'</h3><div class="wallet-context-questions">'+qs.map(q=>button(E(q),'data-wallet-ask="'+E(q+' For '+state.wallet.name+', use saved evidence and flag missing information.')+'" data-context="'+key+'"')).join('')+'</div></div>';const rail=['books','banking','company'].includes(route)&&page.querySelector('.sx-rail');if(rail){el.classList.add('sx-rail-card');el.querySelector('h3').textContent='Questions to ask Fran';rail.querySelector('.sx-rail-card')?.after(el);continue;}const hdr=(route==='payroll'&&(page.querySelector('.wallet-sources')||page.querySelector('.wallet-labor-progress')))||page.querySelector('.wallet-heading')||page.querySelector('.main-hdr');if(hdr)hdr.after(el);else page.prepend(el);}
}
function evidencePanel(){
 const r=records('labor_week_results').sort((a,b)=>String(b.data.week_start).localeCompare(String(a.data.week_start)))[0]?.data;
 const latest=complete().at(-1),sales=r?.operating_sales,work=r?.hours;
 const cells=[['Accounting',latest?.label,latest?.status,state.books?.[0]?.last_synced,'Reported P&L; a recorded close date is required for closed books.'],['Operating sales',sales?date(r.week_start)+' – '+date(r.week_end):'No import',sales?.final?'Final source report':'Provisional',sales?.collected_at,sales?.definition||sales?.source||'Weekly sales source needed.'],['Worked hours',work?date(r.week_start)+' – '+date(r.week_end):'No import',work?.final?'Closed timesheets':'Approvals unverified',work?.collected_at,work?.source||'When I Work source import needed.']];
 dialog('Evidence behind your wallet','<p>Each source keeps its own dates and definition. Comparable periods and scope are required before a variance is final.</p><div class="wallet-evidence-grid">'+cells.map(([name,period,status,updated,note])=>'<article><h3>'+E(name)+'</h3>'+badge(status||'Missing','notice')+'<dl><dt>Period</dt><dd>'+E(period||'Not available')+'</dd><dt>Collected</dt><dd>'+E(updated?new Date(updated).toLocaleString():'Not recorded')+'</dd></dl><p>'+E(note)+'</p></article>').join('')+'</div><h3>Keep the sales measures separate</h3><p>'+E(sales&&r.sales?'Operating report: '+money(sales.amount)+'. Rachel workbook: '+money(r.sales.amount)+'. These have different source definitions and are not interchangeable.':'Confirm the sales definition before comparing a projection with actuals.')+'</p>'+footer('books','Which evidence is missing from my wallet?'),true);
}
// Next moves: at most three, priorities first, then the work that unlocks next week's plan. Planning lives in the hero.
function actionWorkspace(latest,pending){
 const host=$('wallet-home');if(!host)return;host.querySelector('.wallet-work-queue')?.remove();host.querySelector('.wallet-priorities')?.remove();
 let hidden={};try{hidden=JSON.parse(localStorage.getItem('fran-priorities-'+state.wallet.id)||'{}');}catch{}
 const items=M.priorities(state,life).filter(x=>!(hidden[x.id]>Date.now())).slice(0,1).map(x=>({domain:x.service||'books',title:x.title,note:x.finding,action:'Review next step',attrs:'data-priority="'+E(x.id)+'"'}));
 if(pending.some(p=>p.source_incomplete))items.push({domain:'books',title:'Complete missing sales',note:'Accounting ratios are withheld until the main revenue entries arrive.',action:'Review accounting',attrs:'data-wallet-route="books"'});
 if(latest){const x=M.reconcileLabor(state,latest.key);if(x.difference!=null&&Math.abs(x.difference)>.01)items.push({domain:'books',title:'Reconcile '+money(Math.abs(x.difference))+' of labor',note:'Gusto payroll and QuickBooks labor differ for '+latest.label+'.',action:'Open reconciliation',attrs:'data-wallet-reconcile="'+latest.key+'"'});}
 const shown=items.slice(0,3),queue=document.createElement('section');queue.className='wallet-work-queue wallet-priorities sx-moves';
 queue.innerHTML='<div class="sx-section-head"><h2>Next moves</h2><p>From your records. Review the evidence before acting.</p>'+(Object.keys(hidden).length?button('Show snoozed','data-priority-reset'):'')+button('Sources & dates','data-wallet-evidence')+'</div>'
  +(shown.length?'<ol>'+shown.map((x,i)=>'<li><span class="sx-move-n" aria-hidden="true">'+(i+1)+'</span><div><small>'+E(supportName(x.domain))+'</small><h3>'+E(x.title)+'</h3><p>'+E(x.note)+'</p></div>'+button(E(x.action)+' '+icon(),x.attrs)+'</li>').join('')+'</ol>':'<p class="sx-empty-line">Nothing needs your attention from the available records. This is not a complete risk assessment.</p>');
 (host.querySelector('[data-home-moves]')||host.querySelector('.sx-main'))?.append(queue);
 queue.querySelector('[data-priority-reset]')?.addEventListener('click',()=>{localStorage.removeItem('fran-priorities-'+state.wallet.id);actionWorkspace(latest,pending);});
 queue.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>priorityDetail(b.dataset.priority));
 if(window.FRAN_ACTIONS){const saved=document.createElement('button');saved.type='button';saved.className='wallet-button sx-quiet';saved.textContent='View saved next steps';saved.onclick=()=>{const d=dialog('Your saved next steps','');window.FRAN_ACTIONS.list(d.querySelector('.wallet-dialog-content'));};queue.append(saved);}
}
// Latest week with sales and worked hours; labor % is the same estimate the Payroll hero uses.
function weekLabor(){const weeks=laborWeeks();const w=[...weeks].reverse().find(x=>x.sales>0&&x.hours!=null)||[...weeks].reverse().find(x=>x.sales!=null);if(!w)return null;const wr=costPerHour(w.end||addDays(w.start,6))||costPerHour(),pct=wr&&w.hours!=null&&w.sales>0?w.hours*wr.rate/w.sales*100:null;const end=new Date(w.start+'T12:00:00Z').getUTCDay()===1?addDays(w.start,6):w.end||addDays(w.start,6);return {w,pct,label:short(w.start)+' – '+short(end),provisional:w.salesFinal===false||w.hoursFinal===false};}
function operatingPulse(){
 const host=$('wallet-home');if(!host)return;host.querySelector('.wallet-operating-pulse')?.remove();host.querySelector('.sx-home-cards')?.remove();
 const all=fin(),pending=all.filter(p=>p.partial),latest=all.filter(p=>!p.partial).at(-1),wk=weekLabor(),accounts=M.accounts(state).filter(a=>cashTypes.includes(a.type)),cash=M.cash(state),review=M.bankReview(state).length>0,goal=state.goals?.find(g=>g.metric==='booked_labor_percent'),target=goal?Number(goal.target):null,debts=records('debt'),due=tasks()[0];
 const pct=wk?.pct,over=pct!=null&&target!=null&&pct>target+.05;
 const hero=sxHero({cls:'wallet-operating-pulse sx-home-hero',label:'This week',eyebrow:'This week · '+state.wallet.name,title:'Last week’s sales',value:wk?.w.sales!=null?money(wk.w.sales):'Not in yet',muted:wk?.w.sales==null,
  caption:wk?wk.label+' · '+(wk.w.salesSource||'weekly sales')+(wk.provisional?' · provisional until sales and hours are final':''):'Enter last week’s sales when you plan next week, and Fran keeps the weekly history.',
  action:'<div class="sx-hero-next"><span>Next</span>'+button('Plan next week '+icon(),'data-la-open',true)+'</div>',
  strip:[['Cash in bank',review?'Review connections':accounts.length?money(cash):'Not connected',review?'Possible duplicate account · total withheld':accounts.length?accounts.length+' account'+(accounts.length===1?'':'s')+' · balance snapshot':'Connect your bank to see it','data-wallet-cash'],
   ['Labor % · estimate',pct!=null?pct.toFixed(1)+'%':'Not yet',pct!=null?(target!=null?(over?'↑ '+(pct-target).toFixed(1)+' pts over':'✓ within')+' your '+num(target)+'% goal':'Set a labor goal on Payroll'):'Needs sales and worked hours','data-wallet-route="payroll"'],
   ['Worked hours',wk?.w.hours!=null?num(wk.w.hours)+' h':'Not in yet',wk?.w.hours!=null?(wk.w.hoursFinal?'Closed timesheets':'Provisional · manager closeout needed'):'Import When I Work timesheets']]});
 const cards='<div class="sx-cards sx-home-cards">'
  +sxCard(latest?{tone:(latest.net||0)<0?'cost':'cash',icon:'chart',label:'Net income · '+latest.label,value:money(latest.net),neg:(latest.net||0)<0,sub:bookState(latest),attrs:'data-wallet-finance="net"'}:{tone:'muted',empty:true,icon:'chart',label:'Net income',value:'Not available',sub:'Connect QuickBooks to see monthly results.',cta:'Connect',attrs:'data-wallet-route="books"'})
  +(debts.length?sxCard({tone:'cost',icon:'loan',label:'Loan balance',value:money(debts.reduce((n,r)=>n+(M.number(r.data.balance)||0),0)),neg:true,sub:debts.map(r=>r.data.lender).filter(Boolean).join(', ')||debts.length+' loan',attrs:'data-wallet-debt'}):sxCard(latest?{tone:'sales',icon:'dollar',label:'Revenue · '+latest.label,value:money(latest.income),sub:bookState(latest),attrs:'data-wallet-finance="income"'}:{tone:'muted',empty:true,icon:'dollar',label:'Revenue',value:'Not available',sub:'Connect QuickBooks to see revenue.',cta:'Connect',attrs:'data-wallet-route="books"'}))
  +(due?sxCard({tone:'hours',icon:'calendar',label:'Next deadline',value:date(due.data.due),sub:cleanTitle(due.data.title)+(suggested(due.data)?' · suggested, confirm':''),attrs:'data-wallet-task="'+E(due.id)+'"'}):sxCard({tone:'muted',empty:true,icon:'calendar',label:'Next deadline',value:'None recorded',sub:'Add renewal dates so nothing lapses.',cta:'Compliance',attrs:'data-wallet-route="entity"'}))+'</div>';
 const slot=host.querySelector('[data-home-hero]');if(slot)slot.innerHTML=hero+cards;
 actionWorkspace(latest,pending);
 for(const [id,key]of [['wallet-insurance','insurance'],['wallet-compliance','entity']]){const h=$(id);if(h){h.querySelector('.wallet-provider-card')?.remove();h.insertAdjacentHTML('beforeend',providerCard(key));}}
 for(const id of ['wallet-accounting-insight','wallet-finance-intro','page-company'])$(id)?.querySelector(':scope>.wallet-provider-card')?.remove();
 const insurance=$('wallet-insurance');insurance?.classList.add('wallet-policy-cards');
 const r=records('labor_week_results').sort((a,b)=>String(b.data.week_start).localeCompare(String(a.data.week_start)))[0]?.data,sales=r?.operating_sales||r?.sales;
 const daily=$('daily-sales');if(daily&&r){daily.querySelector('.wallet-weekly-sales')?.remove();daily.insertAdjacentHTML('afterbegin','<section class="wallet-weekly-sales wallet-trust-note"><span class="wallet-eyebrow">VERIFIED REPORT PERIOD</span><h3>Weekly operating results · '+E(date(r.week_start)+' – '+date(r.week_end))+'</h3><div class="wallet-pulse-grid"><article><small>Actual net sales</small><strong>'+money(sales?.metric==='net_sales'?sales.amount:null)+'</strong><span>'+E(sales?.metric==='net_sales'?sales.source:'Sales definition awaiting verification')+'</span></article><article><small>Worked timesheet hours</small><strong>'+num(r.hours?.amount)+' h</strong><span>Separate from paid payroll hours</span></article></div><p>Weekly collection can populate this view before accounting closes. Daily imports remain available below; weekly totals are not fabricated into daily rows.</p></section>');}
}

