// Payroll header: one primary (Plan next week) and a quiet "More" menu. Other modules append their buttons
// to this header at different times, so a childList observer re-files them; every handler stays on its button.
function payrollHeader(){const hdr=$('page-payroll')?.querySelector('.main-hdr');if(!hdr)return;let group=hdr.querySelector(':scope>.payroll-hdr-actions');
 if(!group){group=document.createElement('div');group.className='payroll-hdr-actions';group.innerHTML='<details class="payroll-more"><summary>More<span class="sr-only"> payroll actions</span></summary><div class="payroll-more-menu" role="group" aria-label="More payroll actions"></div></details>';hdr.append(group);group.querySelector('.payroll-more-menu').addEventListener('click',e=>{if(e.target.closest('button'))group.querySelector('.payroll-more').open=false;});group.querySelector('.payroll-more').addEventListener('keydown',e=>{if(e.key==='Escape'){const d=e.currentTarget;d.open=false;d.querySelector('summary').focus();}});new MutationObserver(payrollHeader).observe(hdr,{childList:true});}
 // One "Plan next week" primary per page: when the labor hero shows its own, the header copy moves into More.
 const menu=group.querySelector('.payroll-more-menu'),hero=$('page-payroll')?.querySelector('.wl-hero [data-la-open]'),primary=hdr.querySelector('[data-la-open]:not(.wl-next)');
 // The support entry point stays visible beside More; everything else files into the menu.
 const support=[...hdr.children].find(b=>b.tagName==='BUTTON'&&b.classList.contains('eco-support')&&!b.classList.contains('eco-milestone-button'));if(support)group.insertBefore(support,group.querySelector('.payroll-more'));
 for(const b of [...hdr.children])if(b.tagName==='BUTTON'&&(b!==primary||hero))menu.append(b);
 if(primary&&hero&&primary.parentElement!==menu)menu.prepend(primary);
 if(primary&&!hero&&primary.parentElement!==group)group.prepend(primary);
 const more=group.querySelector('.payroll-more');more.hidden=!menu.children.length;}
document.addEventListener('click',e=>{const open=document.querySelector('.payroll-more[open]');if(open&&!open.contains(e.target))open.open=false;});
function render(){scheduled=false;if(!state?.wallet||state.wallet.access_role)return;document.body.classList.add('wallet-refined');home();insurance();payroll();compliance();accounting();finance();freshness();nextPriorities();companyProfile();contextualTools();setupEntrypoints();operatingPulse();contextualPrompts();payrollHeader();}
function queue(){if(!scheduled){scheduled=true;setTimeout(render,0);}}
window.addEventListener('fran:document-preview',e=>{if(state&&docs().some(r=>r.id===e.detail?.id))preview(e.detail.id);});
window.addEventListener('fran:location',e=>{if(state?.wallet?.id!==e.detail?.wallet?.id){epoch++;life=null;year=null;calendarMonth=null;financeView='home';companyView='profile';document.querySelectorAll('.wallet-surface').forEach(n=>n.remove());document.body.classList.remove('wallet-refined');$('wallet-dialog')?.close();}state=e.detail;queue();});
window.addEventListener('fran:readiness',e=>{if(e.detail.location?.wallet?.id===state?.wallet?.id){life=e.detail.life;queue();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state)return;const a=b.dataset;
 if(a.agOpen){e.preventDefault();agSheet(a.agOpen);return;}if('finSources' in a){financeSources();return;}
 if(a.walletPreview||a.rbFile){e.preventDefault();e.stopImmediatePropagation();preview(a.walletPreview||a.rbFile);return;}
 if(a.walletDownload){e.preventDefault();const native=[...document.querySelectorAll('[data-download]')].find(x=>x.dataset.download===a.walletDownload);native?.click();return;}
 if('walletLending' in a){$('wallet-dialog')?.close();dispatchEvent(new CustomEvent('fran:room-audience',{detail:{audience:'lender'}}));switchTab('documents');return;}
 if(a.walletRoute){$('wallet-dialog')?.close();switchTab(a.walletRoute);return;}
 if(a.walletService){$('wallet-dialog')?.close();service(a.walletService,a.note||'');return;}
 if(a.walletAsk){ask(a.walletAsk,a.context||'books');return;}
 if('walletConnectBank' in a){$('wallet-dialog')?.close();switchTab('banking');requestAnimationFrame(()=>$('connect-bank')?.click());return;}
 if(a.companyView){companyView=a.companyView;if(!$('page-company')?.classList.contains('active'))switchTab('company');companyProfile();setupEntrypoints();$('page-company')?.querySelector('.sx-tabs [aria-current=page]')?.focus();return;}
 if('acctFiles' in a){accountingFiles();return;}if('acctReports' in a){const r=$('accounting-detailed-reports');if(r){r.open=true;r.scrollIntoView({block:'start'});r.querySelector('summary')?.focus();}return;}
 if('walletCash' in a){cashDetail();return;}if('walletDebt' in a){debtDetail(a.debtId);return;}
 if(a.finView){$('wallet-dialog')?.close();financeView=a.finView;if(!$('page-banking')?.classList.contains('active'))switchTab('banking');finance();requestAnimationFrame(()=>{const s=$('wallet-bank-statements');if('finStatements' in a&&s){s.open=true;s.scrollIntoView({block:'start'});s.querySelector('summary')?.focus();}else $('wallet-finance-intro')?.querySelector('.sx-tabs [aria-current=page]')?.focus();});return;}
 if('finAccount' in a){accountDetail(a.finAccount);return;}
 if(a.walletReconcile){reconciliation(a.walletReconcile);return;}
 if(a.walletFinance||a.walletMonth){accountAnalysis(a.walletFinance||a.walletSeries||'net',a.walletMonth);return;}
 if(a.walletInsView){insuranceView=a.walletInsView;insurance();return;}
 if(a.walletPayMonth){payMonth(a.walletPayMonth);return;}
 if('walletPayTotal' in a){ask('What was my payroll cost?','payroll');return;}
 if(a.walletPerson){employee(a.walletPerson);return;}
 if('walletSchedule' in a){$('fw-payroll')?.querySelector('[data-workspace=schedule]')?.click();return;}
 if('walletEmployees' in a){$('fw-payroll')?.querySelector('[data-workspace=employees]')?.click();return;}
 if(a.walletTask){taskDetail(a.walletTask);return;}
 if(a.calendarStep){const d=new Date(calendarMonth+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(a.calendarStep));calendarMonth=d.toISOString().slice(0,7);compliance();return;}
 if('bookedGoal' in a){bookedGoal();return;}if('walletGoal' in a){goals();return;}if('walletMilestone' in a){milestone();return;}
},true);
